def perfect_match(cands):
    mt={}
    def dfs(i,seen):
        for j in sorted(cands[i], key=lambda x: len([k for k in cands if x in k])):
            if j in seen: continue
            seen.add(j)
            if j not in mt or dfs(mt[j],seen):
                mt[j]=i; return True
        return False
